      const noteFreqs = [261.63, 277.18, 293.66, 311.13, 329.63, 349.23, 369.99, 392.00, 415.30, 440.00, 466.16, 493.88, 523.25];
      const noteNames = ['C4', 'C#', 'D4', 'D#', 'E4', 'F4', 'F#', 'G4', 'G#', 'A4', 'A#', 'B4', 'C5'];
      let lastPlayedFreq = 440;

